SELECT t.Refine_ID, t.Finding_Seq_Nbr, t.Refine_Project_Cd, t.Refine_Table_Nm, t.Refine_Run_Ty, t.Window_Start_Dt, t.Window_End_Dt, t.Refine_Run_Cnt, t.Finding_Ty, t.Finding_Nm, CAST(t.Refine_Rule_ID AS INTEGER) AS Refine_Rule_ID, t.Short_Run_Cnt, t.Refine_Missing_Cnt, t.Blocked_Cnt, t.Lost_Cnt, t.Refine_Case_Cnt, t.Prior_Avg_Val, t.Last_As_Of_Dt, t.Finding_Txt, t.Threshold_Txt, t.Report_Dtts, t.Review_By, t.Review_Dtts, t.Review_Txt, t.Row_Kind, t.Review_Status, t.Finding_Cnt
FROM (
SELECT v.Refine_ID, v.Finding_Seq_Nbr, v.Project_Cd AS Refine_Project_Cd, v.Table_Nm AS Refine_Table_Nm, v.Run_Ty AS Refine_Run_Ty, v.Window_Start_Dt, v.Window_End_Dt, v.Run_Cnt AS Refine_Run_Cnt, v.Finding_Ty, v.Finding_Nm, v.Rule_ID AS Refine_Rule_ID, v.Short_Run_Cnt, v.Missing_Cnt AS Refine_Missing_Cnt, v.Blocked_Cnt, v.Lost_Cnt, v.Case_Cnt AS Refine_Case_Cnt, v.Prior_Avg_Val, v.Last_As_Of_Dt, v.Finding_Txt, v.Threshold_Txt, v.Report_Dtts, v.Review_By, v.Review_Dtts, v.Review_Txt, v.Row_Kind, v.Review_Status, v.Finding_Cnt
FROM (
SELECT f.Refine_ID, f.Finding_Seq_Nbr, f.Project_Cd, f.Table_Nm, f.Run_Ty, f.Window_Start_Dt, f.Window_End_Dt, f.Run_Cnt, f.Finding_Ty, f.Finding_Nm, f.Rule_ID, f.Short_Run_Cnt, f.Missing_Cnt, f.Blocked_Cnt, f.Lost_Cnt, f.Case_Cnt, f.Prior_Avg_Val, f.Last_As_Of_Dt, f.Finding_Txt, f.Threshold_Txt, f.Report_Dtts, f.Review_By, f.Review_Dtts, f.Review_Txt, CASE WHEN f.Finding_Ty IN ('NOT_PICKED', 'TOPUP', 'REPLACED') THEN 'Total' ELSE 'Finding' END AS Row_Kind, CASE WHEN f.Review_By IS NULL THEN 'Open' ELSE 'Reviewed' END AS Review_Status, 1 AS Finding_Cnt FROM HSLABBOSS.GOVT_RGLTRY_SamplingRefinement f
) v
) t
